pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(bytes32 _batcherHash) public {
        vm.prank(address(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001));
